#!/usr/bin/env python3
"""Export reviewed barge/coal registration metadata to shared Java; never edits images."""
import csv
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SHEETS = [('HULL', 'barge-isometric-v3'), ('COAL', 'bulk-isometric-v1')]

def main():
    lines = ['package com.bargeboss.game;', '',
             '/** Registered waterline pivots for the isometric barge and its separate coal layer.',
             ' * Generated by tools/export-barge-runtime.py; no per-frame stretching.',
             ' * Detailed fender/rope guide estimates remain in art-study JSON pending pixel review. */',
             'public final class BargeArt {',
             '    public static final float HULL_FRACTION=.78f;',
             '    private BargeArt() {}']
    for kind, stem in SHEETS:
        with (ROOT / 'docs/art-studies' / (stem + '-registration.csv')).open() as source:
            rows = list(csv.DictReader(source))
        if [int(row['frame']) for row in rows] != list(range(32)):
            raise ValueError('Expected 32 ordered frames: ' + stem)
        scales = [float(row['uniform_scale']) for row in rows]
        if any(not math.isfinite(s) or s <= 0 or s != scales[0] for s in scales):
            raise ValueError('Scale must be finite, positive and uniform')
        lines.append('    public static final float ' + kind + '_SCALE=' + format(scales[0], '.8f') + 'f;')
        for axis in ('x', 'y'):
            values = [float(row['pivot_' + axis]) for row in rows]
            if any(not math.isfinite(v) or not 0 < v < 1 for v in values):
                raise ValueError('Invalid waterline pivot')
            lines.append('    private static final float[] ' + kind + '_' + axis.upper() + '={' + ','.join(format(v, '.8f') + 'f' for v in values) + '};')
    lines += ['    public static float pivotX(boolean coal,int frame) { return (coal?COAL_X:HULL_X)[frame]; }',
              '    public static float pivotY(boolean coal,int frame) { return (coal?COAL_Y:HULL_Y)[frame]; }', '}']
    path = ROOT / 'core/com/bargeboss/game/BargeArt.java'
    path.write_text('\n'.join(lines) + '\n')
    print('Wrote ' + str(path))

if __name__ == '__main__':
    main()
